/* Links do porquê (Rafael 25/11/2026): afirmação que precisa de explicação. t = trecho exato do texto do site. */
(function(){ var B = window.BANCOS && window.BANCOS.farmaco; if (!B) return;
  var AND = 'Andrade, Terapêutica Medicamentosa em Odontologia (livro da disciplina)';
  var MAL = 'Malamed, Manual de Anestesia Local';
  var RANG = 'Rang & Dale, Farmacologia';
  var AHA = 'AHA 2021 (Wilson e cols., Circulation 2021), prevenção da endocardite infecciosa';
  var ANV = 'ANVISA, RDC 20/2011 (antimicrobianos)';
  var P344 = 'Portaria SVS/MS 344/1998 (medicamentos controlados)';
  B.porques = (B.porques || []).concat([
  { t: "o antibiótico mais usado na odontologia", p: "porque cobre bem as bactérias que causam as infecções de origem dentária (estreptococos e boa parte dos anaeróbios da boca), é bem absorvida por via oral, tem poucos efeitos colaterais, é dada de 8 em 8 horas e é barata. Por isso é a 1ª escolha quando o paciente não é alérgico a penicilina. Ex.: paciente com abscesso no 36, sem alergia, depois de drenado: amoxicilina 500 mg de 8 em 8 horas.", fonte: AND },

  /* ---------- Farmacocinética ---------- */
  { t: "principalmente no fígado", p: "O fígado tem a maior quantidade de enzimas de biotransformação do corpo (as do citocromo P450) e recebe todo o sangue que vem do intestino pela veia porta. Essas enzimas deixam o fármaco mais polar (mais 'solúvel em água'), e aí o rim consegue eliminá-lo. Ex.: um paciente com cirrose metaboliza a lidocaína mais devagar, então ela acumula e a dose segura dele fica menor.", fonte: RANG },
  { t: "principalmente pelos rins", p: "O rim filtra o plasma o tempo todo. Depois que o fígado deixa o fármaco mais polar, ele não consegue voltar pela parede do túbulo (não é reabsorvido) e sai na urina. Por isso, em quem tem doença renal, o remédio pode acumular. Ex.: um idoso com insuficiência renal que toma amoxicilina pode precisar de intervalo maior entre as doses, porque ela demora a sair na urina.", fonte: RANG },
  { t: "chega menos fármaco inalterado", p: "O que é absorvido no intestino vai pela veia porta direto para o fígado, que já metaboliza uma parte antes de o fármaco chegar à circulação geral. É por isso que a dose oral de muitos remédios é maior que a dose na veia, que não passa por esse 'pedágio'. Ex.: a morfina por boca precisa de dose bem maior que na veia para dar o mesmo alívio, porque o fígado destrói boa parte na primeira passagem.", fonte: RANG },
  { t: "quanto maior, mais segura a margem", p: "O índice terapêutico mede a distância entre a dose que trata e a dose que intoxica. Como cada paciente responde um pouco diferente, quanto maior essa distância, maior a sobra para um erro de dose ou uma pessoa mais sensível sem chegar ao efeito tóxico. Ex.: a varfarina tem índice terapêutico estreito (pequena diferença entre tratar e sangrar), por isso o INR é conferido sempre; a amoxicilina tem índice largo e quase ninguém intoxica com a dose comum.", fonte: RANG },
  { t: "resposta cai com o uso repetido", p: "Com o uso repetido, os receptores ficam menos sensíveis ou diminuem em número, ou o mediador que o fármaco libera se esgota. Aí a mesma dose passa a dar menos efeito. Quando isso acontece em poucas doses seguidas, chama-se taquifilaxia. Ex.: quem usa descongestionante nasal todo dia percebe que ele vai funcionando cada vez menos.", fonte: RANG },
  { t: "principalmente a albumina", p: "Só a parte LIVRE do fármaco (a que não está presa na proteína) passa para os tecidos, age e é eliminada. A parte presa funciona como reserva. Se dois fármacos disputam a mesma albumina, um 'empurra' o outro e a fração livre sobe, o que pode dar mais efeito ou toxicidade. Ex.: um paciente com varfarina que toma um AINE forte: o AINE disputa a albumina, solta mais varfarina livre e o sangramento aumenta.", fonte: RANG },

  /* ---------- Anestésicos locais ---------- */
  { t: "maior potencial alergênico", p: "Os ésteres são quebrados no plasma pela pseudocolinesterase, e um dos produtos é o PABA (ácido para-aminobenzoico), substância conhecida por causar alergia. As amidas são metabolizadas no fígado e não formam PABA, por isso a alergia verdadeira a elas é raríssima. Ex.: um paciente que teve urticária com procaína pode receber lidocaína (amida), porque ela não forma PABA.", fonte: MAL },
  { t: "as mais usadas, mais seguras", p: "As amidas quase não causam alergia (não geram PABA), são estáveis na solução (aguentam esterilização e armazenamento) e têm boa duração. Por isso substituíram os ésteres na odontologia. Ex.: no dia a dia da clínica os tubetes são de lidocaína, articaína ou mepivacaína, todas amidas; éster injetável quase não se vê mais.", fonte: MAL },
  { t: "potente e de longa duração", p: "A bupivacaína é muito lipossolúvel, então entra fácil na membrana do nervo e precisa de concentração baixa (0,5%) para funcionar: isso é potência. E ela se prende muito às proteínas do canal de sódio, então demora para sair dali: isso é duração longa. Ex.: numa cirurgia de terceiro molar demorada, a bupivacaína mantém a anestesia e ainda segura a dor das primeiras horas depois.", fonte: MAL },
  { t: "Não acelera o metabolismo", p: "O vasoconstritor só fecha os vasos do local da injeção, segurando o anestésico ali. Quem metaboliza o anestésico (fígado ou plasma) continua no mesmo ritmo; o que muda é que o anestésico chega ao sangue aos poucos. Ex.: com ou sem epinefrina, a lidocaína continua sendo destruída pelo fígado no mesmo ritmo; a diferença é que com epinefrina ela chega ao sangue aos poucos.", fonte: MAL },
  { t: "absorção mais lenta, menos toxicidade sistêmica", p: "Quase todo anestésico local dilata os vasos, então sem vasoconstritor ele 'some' rápido do local para o sangue. Com a epinefrina fechando os vasos, ele fica mais tempo encostado no nervo (efeito mais longo e profundo) e chega ao sangue devagar, dando tempo do corpo metabolizar sem formar pico tóxico. Ex.: lidocaína 2% sem vasoconstritor dá anestesia pulpar de uns 5 a 10 minutos; com epinefrina 1:100.000 dura cerca de 60 minutos.", fonte: MAL },
  { t: "mais forma ionizada", p: "O anestésico é uma base fraca. No tecido inflamado o pH é ácido, então sobram íons H+ que se grudam na molécula e ela fica com carga (ionizada). Molécula com carga não atravessa a membrana de gordura do nervo, e pouca chega ao canal de sódio: por isso a anestesia falha no dente com abscesso. Ex.: no 46 com abscesso, a infiltração no local inflamado falha; o bloqueio do alveolar inferior, feito longe da inflamação, costuma funcionar.", fonte: MAL },
  { t: "hidrolisada no plasma", p: "O grupo éster extra da articaína é quebrado pelas esterases do sangue, então ela é inativada muito rápido (meia-vida de uns 20 a 30 minutos), além do fígado. Isso não muda a classe dela, que é definida pela ligação da cadeia intermediária, que é amida. Ex.: por ser inativada rápido no sangue, a articaína pode ser usada a 4% (72 mg por tubete) com boa margem de segurança.", fonte: MAL },
  { t: "metemoglobinemia (orto-toluidina)", p: "O fígado transforma a prilocaína em orto-toluidina, que oxida o ferro da hemoglobina (de Fe2+ para Fe3+). Essa metemoglobina não carrega oxigênio, e em dose alta o paciente fica azulado (cianose). Por isso se evita prilocaína em quem já tem pouco oxigênio no sangue. Ex.: paciente que recebeu muitos tubetes de prilocaína e, horas depois, aparece com lábios e unhas azulados, mesmo respirando normalmente.", fonte: MAL },
  { t: "pouca hemostasia, evitar em gestante", p: "A felipressina age em receptores de vasopressina que contraem mais o lado venoso da circulação, quase nada as arteríolas, então segura pouco o sangramento. E por ser parecida com a vasopressina e a ocitocina, pode estimular contração do útero, por isso se evita na gestante. Ex.: numa exodontia com muito sangramento, prilocaína com felipressina deixa o campo mais sangrento do que lidocaína com epinefrina.", fonte: MAL },
  { t: "ligado a reações alérgicas", p: "O metilparabeno é um conservante parecido quimicamente com o PABA, a mesma substância que faz os ésteres darem alergia. Por isso ele foi tirado dos tubetes odontológicos de uso único, que não precisam de conservante contra bactérias. Ex.: um paciente que diz ter 'alergia a anestésico' muitas vezes reagiu, na verdade, ao conservante dos tubetes antigos, e não à lidocaína.", fonte: MAL },

  /* ---------- Doses ---------- */
  { t: "lidocaína 4,4 mg/kg (teto 300 mg)", p: "A dose é por peso porque o anestésico se espalha no volume do corpo: quanto menor a pessoa, mais alta fica a concentração no sangue com a mesma quantidade. O teto existe porque, num paciente muito pesado, a conta por peso daria um valor que já leva a concentração no cérebro a níveis de convulsão. Ex.: paciente de 60 kg: 60 x 4,4 = 264 mg; 264 ÷ 36 = 7,3, ou seja, 7 tubetes. Paciente de 100 kg: a conta daria 440 mg, mas para no teto de 300 mg (8 tubetes).", fonte: AND + '; ' + MAL },
  { t: "teto absoluto da lidocaína, 300 mg", p: "Acima de uns 300 mg a concentração de lidocaína no sangue pode chegar ao nível que afeta o sistema nervoso central (tontura, tremor, convulsão), e esse risco não cresce junto com o peso (gordura não ajuda a metabolizar). Então, mesmo num paciente de 100 kg, não se passa do teto. Ex.: paciente de 90 kg: 90 x 4,4 = 396 mg, mas o máximo é 300 mg; 300 ÷ 36 = 8,3, então 8 tubetes.", fonte: AND + '; ' + MAL },
  { t: "arredonda sempre para baixo", p: "Arredondar para cima já passa da dose máxima. Com 7,3 tubetes calculados, o 8º tubete levaria a 288 mg num paciente cujo limite é 264 mg. A dose máxima é um limite, não uma meta. Ex.: 60 kg com lidocaína 2%: 264 mg ÷ 36 mg = 7,3. Pode 7 tubetes (252 mg); 8 tubetes seriam 288 mg, acima do limite.", fonte: AND },
  { t: "articaína 7 mg/kg (teto 500 mg)", p: "A articaína é inativada muito depressa (o grupo éster é quebrado no sangue, além do fígado), então ela sai do organismo mais rápido e tolera uma dose por kg maior que a lidocaína. Mesmo assim existe teto, porque a quantidade de uma vez no sangue ainda pode intoxicar. Ex.: paciente de 70 kg: 70 x 7 = 490 mg; 490 ÷ 72 = 6,8, então 6 tubetes de articaína 4%.", fonte: AND + '; ' + MAL },
  { t: "dose máxima para essa criança", p: "Como a dose é por peso, a criança pequena chega ao limite com poucos tubetes. A maior parte das intoxicações graves por anestésico local na odontologia aconteceu em crianças que receberam o volume de 'tubete de adulto'. Por isso na criança a conta é sempre feita antes. Ex.: criança de 20 kg com lidocaína 2%: 20 x 4,4 = 88 mg; 88 ÷ 36 = 2,4, então só 2 tubetes, quando um adulto de 60 kg poderia receber 7.", fonte: MAL },
  { t: "0,01 mg/mL = 0,018 mg/tubete", p: "1:100.000 quer dizer 1 g de epinefrina em 100.000 mL. 1 g = 1.000 mg, então 1.000 mg ÷ 100.000 mL = 0,01 mg em cada mL. O tubete tem 1,8 mL: 0,01 x 1,8 = 0,018 mg por tubete. Ex.: 3 tubetes de lidocaína com epinefrina 1:100.000 = 3 x 0,018 = 0,054 mg de epinefrina.", fonte: MAL },
  { t: "Cardiopata: até 0,04 mg", p: "A epinefrina estimula os receptores beta-1 do coração: aumenta frequência e força e o coração gasta mais oxigênio. No coração doente isso pode desencadear arritmia ou angina. Por isso o limite cai de 0,2 mg para 0,04 mg (cerca de 2 tubetes de 1:100.000). Ex.: paciente com angina estável controlada: até 2 tubetes de lidocaína com epinefrina 1:100.000 (2 x 0,018 = 0,036 mg), aspirando e injetando devagar.", fonte: MAL + '; ' + AND },
  { t: "o teto cai para 0,04 mg", p: "A epinefrina acelera o coração e aumenta a força de contração (receptor beta-1), o que faz o músculo cardíaco gastar mais oxigênio. No cardiopata essa folga é pequena, então o limite é 0,04 mg, sempre aspirando para não injetar no vaso. Ex.: paciente que teve infarto há 2 anos e está controlado: 2 tubetes de 1:100.000 (0,036 mg) ficam dentro do limite; o 3º já passaria (0,054 mg).", fonte: MAL + '; ' + AND },
  { t: "Saudável: até 0,2 mg", p: "Acima disso a epinefrina que chega ao sangue já dá taquicardia, aumento da pressão, tremor e ansiedade mesmo em quem tem coração saudável. 0,2 mg equivale a cerca de 11 tubetes de 1:100.000. Ex.: adulto saudável de 60 kg com lidocaína 2% 1:100.000: o limite da lidocaína (7 tubetes = 0,126 mg de epinefrina) chega antes do da epinefrina (11 tubetes).", fonte: MAL },
  { t: "Metade da concentração do 1:100.000", p: "1:200.000 é 1 g em 200.000 mL, ou seja, 0,005 mg por mL: metade. Com metade da epinefrina por tubete, o cardiopata pode receber o dobro de tubetes (cerca de 4) sem passar de 0,04 mg, e a vasoconstrição ainda é suficiente para a maioria dos procedimentos. Ex.: cardiopata com articaína 4% 1:200.000: cada tubete tem 0,009 mg, então 4 tubetes dão 0,036 mg e ficam abaixo de 0,04 mg.", fonte: MAL },
  { t: "PA a partir de 180 x 110", p: "Nessa faixa a pressão já está tão alta que o estresse, a dor e a adrenalina do próprio corpo durante o atendimento podem levar a AVC, infarto ou crise hipertensiva. Por isso o tratamento eletivo é adiado e o paciente vai para o médico controlar a pressão antes. Ex.: paciente chega para extrair o 37 com 190 x 115 mmHg em duas medidas: a extração é remarcada e ele é encaminhado ao médico.", fonte: MAL },
  { t: "Pressão igual ou acima de 180 x 110 mmHg", p: "Com a pressão nesse nível o risco de AVC ou infarto durante o atendimento já é alto só pelo medo e pela dor, que liberam adrenalina do próprio corpo. Por isso o procedimento eletivo é remarcado e o paciente é encaminhado ao médico. Ex.: paciente com 185 x 112 mmHg na cadeira, sem dor aguda: não se faz a restauração eletiva hoje; encaminha ao médico e remarca.", fonte: MAL },
  { t: "Diabético controlado pode receber epinefrina", p: "A epinefrina sobe um pouco a glicose (quebra o glicogênio do fígado), mas a quantidade de um ou poucos tubetes é pequena perto da adrenalina que o próprio corpo solta com dor e medo. No diabético controlado isso é bem tolerado, e anestesia boa ainda reduz o estresse. Ex.: diabético tipo 2 com glicemia controlada, que tomou café e remédio de manhã, faz a restauração com 2 tubetes de lidocaína com epinefrina normalmente.", fonte: MAL },

  /* ---------- Técnica e segurança ---------- */
  { t: "Aspirar sempre", p: "A ponta da agulha pode estar dentro de um vaso sem que a gente perceba. Puxar o êmbolo antes de injetar mostra se vem sangue. Injetar anestésico com epinefrina direto no sangue faz um pico tóxico (taquicardia, tremor, até convulsão), mesmo com dose pequena. Ex.: no bloqueio do alveolar inferior, aspira e vem sangue no tubete: recua um pouco, muda a posição, aspira de novo e só injeta quando não vier sangue.", fonte: MAL },
  { t: "aspiração e injeção lenta", p: "A aspiração evita injetar dentro do vaso. Injetar devagar (cerca de 1 mL por minuto) faz menos dor, porque não estica o tecido de uma vez, e, se uma parte entrar na circulação, a concentração no sangue sobe aos poucos e dá tempo de perceber reação. Ex.: um tubete inteiro de 1,8 mL deve levar cerca de 1 a 2 minutos para ser injetado, não 10 segundos.", fonte: MAL },
  { t: "bloqueio regional é a regra", p: "Nos dentes posteriores inferiores a cortical do osso é grossa e compacta, e o anestésico injetado na mucosa não atravessa até o ápice. Então se deposita o anestésico perto do nervo antes de ele entrar no osso (no forame mandibular), e aí todos os dentes daquele lado ficam anestesiados. Ex.: para tratar o canal do 36, infiltrar no fundo de vestíbulo não anestesia a polpa; faz-se o bloqueio do alveolar inferior.", fonte: MAL },
  { t: "Não pega a vestibular dos molares", p: "A gengiva e a mucosa vestibular dos molares inferiores são do nervo bucal, um ramo do V3 que se separa antes e nem chega perto do forame mandibular. Por isso, para extrair molar, junta-se o bloqueio do bucal ao alveolar inferior. Ex.: para extrair o 46: alveolar inferior + lingual anestesiam dente e lingual, mas a gengiva vestibular só dorme com o bloqueio do bucal.", fonte: MAL },
  { t: "6 a 10 mm acima do plano oclusal", p: "No adulto o forame mandibular fica acima do plano oclusal. Se a agulha entra baixa, o anestésico fica abaixo do ponto onde o nervo entra no canal e a anestesia falha, que é a causa mais comum de falha do alveolar inferior. Ex.: aluno que entra na altura das cúspides dos molares inferiores deposita abaixo do forame e o paciente continua sentindo o dente.", fonte: MAL },
  { t: "recua 1 mm, aspira", p: "Ao tocar o osso a ponta da agulha está encostada no periósteo. Recuar 1 mm evita injetar embaixo do periósteo, o que dói muito, e deixa a ponta no espaço onde o nervo passa, para o anestésico se espalhar em volta dele. Ex.: agulha encostou no osso a uns 20 a 25 mm: volta 1 mm, aspira e só então injeta 1,0 a 1,5 mL.", fonte: MAL },
  { t: "quando o convencional falha", p: "O Gow-Gates deposita o anestésico bem mais alto, no colo do côndilo, onde o V3 ainda está quase todo junto. Assim pega vários ramos com uma só picada e sofre menos com variação anatômica, que é o que costuma fazer o alveolar inferior convencional falhar. Ex.: paciente em que o alveolar inferior já falhou duas vezes no 47: o Gow-Gates costuma resolver com uma picada só.", fonte: MAL },
  { t: "indicada no trismo", p: "O Vazirani-Akinosi é feito com a boca FECHADA, com a agulha paralela ao plano oclusal. Como não precisa abrir a boca, serve justamente para o paciente com trismo, que não consegue abrir o suficiente para o bloqueio convencional. Ex.: paciente com pericoronarite no 38 que abre só 1 cm de boca: o Vazirani-Akinosi permite anestesiar de boca fechada.", fonte: MAL },
  { t: "trismo (pterigóideo)", p: "No bloqueio do alveolar inferior a agulha passa perto ou através do músculo pterigóideo medial. Se ele é machucado, sangra (hematoma) ou inflama, entra em espasmo e o paciente não consegue abrir a boca nos dias seguintes. Ex.: dois dias depois de um bloqueio do alveolar inferior, o paciente volta com dor ao abrir a boca e abertura de só 2 cm.", fonte: MAL },
  { t: "paralisia facial transitória (nervo facial)", p: "Se a agulha vai fundo demais e passa da borda de trás do ramo da mandíbula, o anestésico cai dentro da parótida, por onde passa o nervo facial (VII). Os músculos da expressão daquele lado param até o anestésico passar, por isso é transitória. Ex.: logo depois do bloqueio, o paciente não consegue fechar o olho daquele lado nem sorrir simétrico; volta ao normal em algumas horas.", fonte: MAL },
  { t: "Nasopalatino: papila incisiva, 0,2 a 0,3 mL", p: "A mucosa do palato é grudada no osso, sem espaço para o líquido se espalhar. Volume grande ali aumenta a pressão, dói e pode deixar a mucosa sem sangue (isquemia). Pouco volume já basta porque o nervo sai bem embaixo da papila. Ex.: para extrair o 11, depois da infiltração vestibular, bastam 0,2 a 0,3 mL na papila incisiva para anestesiar o palato da região.", fonte: MAL },
  { t: "Parassimpático: saliva aquosa e abundante", p: "A acetilcolina do parassimpático age nos receptores muscarínicos das glândulas e manda secretar muita água e eletrólitos. O simpático, pela noradrenalina, estimula mais a secreção de proteínas, e por isso a saliva sai grossa e escassa, como a boca seca no nervosismo. Ex.: antes de uma prova (nervoso, simpático ativado) a boca fica seca e a saliva grossa; no almoço tranquilo (parassimpático) a boca enche de saliva rala.", fonte: RANG },

  /* ---------- Antibióticos ---------- */
  { t: "bactericida, age na parede celular", p: "A amoxicilina se liga às enzimas (PBPs) que montam o peptidoglicano, a 'malha' da parede da bactéria. Sem essa malha, a bactéria que está crescendo não aguenta a pressão interna e estoura: por isso ela mata (bactericida), e não só para o crescimento. Ex.: as bactérias de uma infecção dentária em multiplicação morrem com a amoxicilina; por isso a melhora costuma aparecer em 48 a 72 horas.", fonte: RANG },
  { t: "É destruída pelas betalactamases", p: "Algumas bactérias produzem betalactamases, enzimas que quebram o anel betalactâmico, que é justamente a parte da amoxicilina que age. Com o anel quebrado o antibiótico não funciona. O clavulanato serve para 'distrair' essas enzimas. Ex.: infecção que não melhorou com amoxicilina sozinha pode ser por bactéria produtora de betalactamase; aí se pensa em amoxicilina + clavulanato.", fonte: RANG },
  { t: "nada de amoxicilina, com ou sem clavulanato", p: "A alergia é à estrutura da penicilina, e a amoxicilina É uma penicilina. O clavulanato só protege a amoxicilina das enzimas da bactéria; ele não muda a molécula que o sistema imune reconhece, então o risco de reação grave continua igual. Ex.: paciente que já teve inchaço na garganta com penicilina: nem amoxicilina nem amoxicilina + clavulanato; usa-se azitromicina ou clindamicina no tratamento.", fonte: AND },
  { t: "costuma AUMENTAR a diarreia", p: "O clavulanato amplia o espectro e mata mais bactérias da flora do intestino, e ele mesmo irrita o tubo digestivo. Por isso a diarreia é bem mais comum com amoxicilina + clavulanato do que com amoxicilina sozinha. Ex.: paciente que toma amoxicilina + clavulanato por 7 dias tem mais chance de diarreia do que com amoxicilina sozinha.", fonte: AND },
  { t: "não substituem drenagem nem remoção da causa", p: "O abscesso é uma bolsa de pus sem circulação por dentro, e o antibiótico só chega pelo sangue. Drenar tira as bactérias e a pressão, e tratar a causa (canal, extração) acaba com a fonte. Sem isso a infecção volta quando o antibiótico para. Ex.: abscesso no 36 tratado só com amoxicilina melhora por uns dias e volta quando o remédio acaba, porque o dente necrosado continua lá.", fonte: AND },
  { t: "antibiótico nunca substitui", p: "O antibiótico chega pelo sangue e não entra bem no pus do abscesso, que não tem vaso. Quem resolve é drenar e tirar a causa (polpa necrosada, dente); o antibiótico só ajuda quando a infecção se espalha ou o paciente tem febre e mal-estar. Ex.: paciente com face inchada por abscesso do 46: primeiro drena e abre o dente; o antibiótico entra junto, não no lugar.", fonte: AND },
  { t: "o antibiótico é complemento", p: "O pus do abscesso fica numa cavidade sem circulação, onde o antibiótico mal chega. Por isso ele só complementa: o que cura é drenar e tirar a causa. Ex.: abscesso localizado, sem febre: drenagem e tratamento do canal costumam bastar; com febre e inchaço se espalhando, soma-se o antibiótico.", fonte: AND },
  { t: "só paciente de alto risco", p: "A bacteremia de boca acontece também ao escovar e mastigar, todo dia. Por isso a profilaxia só compensa onde uma endocardite seria muito grave: prótese de válvula, endocardite prévia, algumas cardiopatias congênitas e transplantado cardíaco com valvopatia. Nos outros, o risco do antibiótico supera o benefício. Ex.: paciente com prótese de válvula aórtica que vai extrair o 36 faz profilaxia; paciente com sopro inocente ou com stent coronário não faz.", fonte: AHA },
  { t: "30 a 60 min", p: "Esse é o tempo para a amoxicilina tomada por via oral ser absorvida e chegar ao pico da concentração plasmática bem na hora em que o procedimento solta bactérias no sangue (bacteremia). Dada muito antes, ela já estaria caindo; dada depois, chegaria atrasada. Ex.: paciente com prótese valvar, extração marcada às 14h: toma 2 g de amoxicilina (4 cápsulas de 500 mg) entre 13h e 13h30.", fonte: AHA },
  { t: "Clindamicina não é mais recomendada", p: "Mesmo em dose única, a clindamicina causa mais reações graves, principalmente a colite por Clostridioides difficile (diarreia grave), do que as outras opções. Por isso a AHA 2021 tirou ela da lista para o alérgico. Ex.: paciente de alto risco e alérgico a penicilina: em vez de clindamicina, recebe azitromicina 500 mg, 30 a 60 minutos antes.", fonte: AHA },
  { t: "Alérgico: azitromicina ou claritromicina 500 mg", p: "Os macrolídeos (azitromicina, claritromicina) têm uma estrutura totalmente diferente da penicilina e não dão reação cruzada com ela. Por isso são a alternativa para quem é alérgico. Ex.: paciente com endocardite prévia e alergia a penicilina vai extrair o 26: azitromicina 500 mg em dose única antes do procedimento.", fonte: AHA },

  /* ---------- Anti-inflamatórios e analgésicos ---------- */
  { t: "Inibir a COX-1 = lesão gástrica e mais sangramento", p: "A COX-1 do estômago faz prostaglandinas que aumentam o muco e o bicarbonato e diminuem o ácido. Na plaqueta, a COX-1 faz o tromboxano, que faz ela grudar. Bloqueando a COX-1, a mucosa fica sem proteção e a plaqueta agrega menos. Ex.: paciente com gastrite que toma ibuprofeno depois de uma extração pode ter dor no estômago e o alvéolo sangrando mais.", fonte: RANG },
  { t: "poupa o estômago, mas tem risco cardiovascular", p: "O COX-2 seletivo corta a prostaciclina dos vasos (que dilata e impede a plaqueta de grudar), mas deixa o tromboxano da plaqueta (COX-1) funcionando. O equilíbrio pende para o lado da trombose, por isso aumenta infarto e AVC. Ex.: paciente com gastrite e sem doença cardíaca pode usar celecoxibe por poucos dias; paciente que já infartou, não.", fonte: RANG },
  { t: "os COX-2 seletivos AUMENTAM o risco cardiovascular", p: "Eles bloqueiam a prostaciclina do vaso, que protege contra trombose, sem bloquear o tromboxano da plaqueta, que favorece trombose. Fica o lado pró-trombótico sem contrapeso, e por isso sobe o risco de infarto e AVC. Ex.: o rofecoxibe (Vioxx) foi retirado do mercado em 2004 porque aumentou os casos de infarto e AVC.", fonte: RANG },
  { t: "AINE + varfarina: mais sangramento", p: "São três efeitos somando: a varfarina reduz os fatores de coagulação, o AINE atrapalha a plaqueta (menos tromboxano) e ainda irrita o estômago. Além disso, alguns AINEs tiram a varfarina da albumina e aumentam a parte livre dela no sangue. Ex.: paciente com varfarina que toma diclofenaco por conta própria depois de uma extração e o alvéolo continua sangrando no dia seguinte.", fonte: RANG },
  { t: "pouco efeito na plaqueta", p: "Dipirona e paracetamol agem mais na COX do sistema nervoso central e têm efeito fraco e reversível na COX da plaqueta. Então não aumentam o sangramento como o AAS e os AINEs, e por isso são a escolha para dor em quem usa anticoagulante. Ex.: paciente com varfarina depois de uma exodontia: dipirona 500 mg a 1 g de 6 em 6 horas controla a dor sem aumentar o sangramento.", fonte: RANG + '; ' + AND },
  { t: "a dipirona é a escolha mais segura", p: "A dipirona quase não interfere na plaqueta nem lesa o estômago, então não soma sangramento ao efeito da varfarina, como fariam o AAS e os AINEs. Ex.: idoso com varfarina e INR controlado, dor depois de extração: dipirona em vez de ibuprofeno ou AAS.", fonte: AND },
  { t: "Paracetamol em excesso = fígado", p: "Uma pequena parte do paracetamol vira NAPQI, um metabólito tóxico que o fígado neutraliza com glutationa. Em dose alta a glutationa acaba, o NAPQI sobra e destrói as células do fígado. Por isso o limite de 4 g por dia no adulto. Ex.: paciente que toma paracetamol 750 mg de 4 em 4 horas o dia todo chega a 4,5 g por dia e já passou do limite de 4 g.", fonte: RANG },
  { t: "Dipirona: agranulocitose rara", p: "Em pouquíssimas pessoas a dipirona provoca uma reação do sistema imune contra os neutrófilos, que caem muito e deixam o paciente sem defesa contra infecção. É rara, por isso a ANVISA manteve a dipirona no Brasil, enquanto alguns países a proibiram. Ex.: paciente que toma dipirona e, dias depois, aparece com febre alta e feridas na boca deve parar o remédio e fazer hemograma.", fonte: RANG + '; ANVISA, Painel Internacional de Avaliação da Segurança da Dipirona (2001)' },
  { t: "analgésicos mais usados depois de procedimentos", p: "A dor depois da maioria dos procedimentos é leve a moderada, e dipirona e paracetamol dão conta dela sem lesar o estômago e sem aumentar o sangramento da ferida, além de serem baratos. Ex.: depois de uma extração simples, o mais comum é prescrever dipirona 500 mg a 1 g de 6 em 6 horas, se houver dor.", fonte: AND },
  { t: "como analgésico após exodontia", p: "O AAS acetila a COX-1 da plaqueta de forma irreversível: aquela plaqueta não agrega mais pelo resto da vida dela (uns 7 a 10 dias). Depois de uma extração isso aumenta o sangramento do alvéolo. Ex.: paciente que tomou AAS para dor depois de extrair o 48 e voltou com o alvéolo sangrando à noite.", fonte: RANG },
  { t: "Evitar na gestante e com varfarina", p: "Na gestante, principalmente da metade da gravidez em diante, o AINE pode fechar antes da hora o ducto arterioso do bebê e diminuir o líquido amniótico. Com varfarina, soma sangramento: o AINE atrapalha a plaqueta e irrita o estômago. Ex.: gestante de 30 semanas com dor depois de um tratamento: paracetamol, não ibuprofeno.", fonte: RANG + '; FDA, alerta sobre AINE a partir de 20 semanas de gestação (2020)' },
  { t: "sem suspender o remédio", p: "Parar o anticoagulante expõe o paciente a trombose, AVC ou embolia, que são muito mais graves que o sangramento de uma extração simples. Esse sangramento se controla no local, com sutura, gaze com pressão, esponja hemostática e ácido tranexâmico. Ex.: paciente com fibrilação atrial, varfarina e INR 2,5 no dia: extrai o 45 sem parar o remédio, com sutura e gaze com ácido tranexâmico.", fonte: AND },

  /* ---------- Corticoides e benzodiazepínicos ---------- */
  { t: "dexametasona em dose única, VO, cerca de 1 hora antes", p: "O corticoide age mudando a produção de proteínas dentro da célula, o que leva algum tempo. Dado antes da cirurgia, ele já está agindo quando a inflamação começa e reduz o edema e o trismo desde o início. Ex.: cirurgia de 38 e 48 incluso marcada às 10h: dexametasona 8 mg por via oral às 9h.", fonte: AND },
  { t: "Dose única não suprime a suprarrenal", p: "A suprarrenal só 'desliga' a produção de cortisol quando recebe corticoide de fora todos os dias por semanas. Uma dose única é usada e eliminada antes de o eixo hipotálamo-hipófise-suprarrenal se adaptar. Ex.: paciente saudável que toma 1 comprimido de dexametasona antes do terceiro molar não precisa de desmame; quem toma prednisona há meses, sim, precisa de cuidado.", fonte: AND + '; ' + RANG },
  { t: "diazepam VO cerca de 1 h antes", p: "O midazolam é absorvido e começa a agir rápido (cerca de 30 minutos) e dura pouco. O diazepam leva mais tempo para chegar ao pico no sangue (cerca de 1 hora) e dura bem mais. O horário de tomar acompanha esse tempo de cada um. Ex.: paciente ansioso com consulta às 15h: diazepam por volta das 14h, ou midazolam por volta das 14h30.", fonte: AND },
  { t: "Paciente com acompanhante e sem dirigir", p: "O benzodiazepínico deixa sonolência, reflexo lento e às vezes amnésia por horas depois da consulta. O paciente não consegue reagir bem no trânsito nem lembrar das orientações, por isso alguém vai com ele. Ex.: paciente que tomou midazolam antes da extração vai embora de carona ou de táxi com um acompanhante, nunca dirigindo.", fonte: AND },
  { t: "Antagonista do benzodiazepínico = flumazenil", p: "O flumazenil se encaixa no mesmo ponto do receptor GABA-A onde o benzodiazepínico age, mas sem ativar nada: ele ocupa o lugar e tira o efeito. A naloxona faz o mesmo no receptor opioide, por isso não serve para benzodiazepínico. Ex.: paciente sedado com midazolam que fica sonolento demais e respirando pouco recebe flumazenil na veia, não naloxona.", fonte: RANG },

  /* ---------- Do glossário (verbetes) ---------- */
  { t: "validade de 30 dias e vale só no estado em que foi emitida", p: "Benzodiazepínico é psicotrópico (lista B1) e pode causar dependência e abuso, por isso tem controle especial. O talão da Notificação B é numerado pela Vigilância Sanitária do estado, e só farmácia daquele estado consegue registrar e conferir essa numeração. O prazo curto de 30 dias impede que a receita seja guardada e usada muito depois. Ex.: o dentista de Petrópolis faz a receita azul de diazepam; vale em qualquer farmácia do RJ por 30 dias, mas uma farmácia de Juiz de Fora (MG) não aceita.", fonte: P344 },
  { t: "2 vias, uma fica na farmácia, vale 10 dias", p: "É regra da ANVISA para frear o uso de antibiótico sem necessidade, que cria bactérias resistentes. A via que fica retida comprova a venda com receita, e a validade curta garante que o remédio é para aquela infecção, e não guardado para depois. Ex.: receita de amoxicilina feita no dia 1: a farmácia fica com a 1ª via e o paciente pode comprar até o dia 10; no dia 15 precisa de receita nova.", fonte: ANV },
  { t: "válida por 10 dias a partir da emissão", p: "A validade curta existe porque a receita é para uma infecção que está acontecendo agora. Junto com a retenção da 1ª via, isso evita que o antibiótico seja comprado e usado depois por conta própria, o que favorece a resistência bacteriana. Ex.: receita de azitromicina emitida em 20/11 vale até 30/11; o paciente que só vai à farmácia em 05/12 precisa de receita nova.", fonte: ANV },
  { t: "tem 2 vias e vale 10 dias", p: "A ANVISA passou a controlar a venda de antimicrobianos em 2010-2011 para reduzir a automedicação e a resistência bacteriana: a farmácia retém uma via como prova e a receita perde a validade rápido. Ex.: o paciente leva as duas vias da receita de amoxicilina; a farmácia carimba e fica com a 1ª, e ele guarda a 2ª.", fonte: ANV },
  { t: "No tubete é o vasoconstritor mais usado", p: "A epinefrina age nos receptores alfa-1 dos vasos da mucosa e contrai bem as arteríolas, então segura o anestésico no lugar e controla o sangramento melhor que a felipressina. Por isso é o padrão dos tubetes, respeitando o limite de dose no cardiopata. Ex.: o tubete mais comum no consultório é lidocaína 2% com epinefrina 1:100.000.", fonte: MAL },
  { t: "0,2 mg no saudável (11 tubetes)", p: "Cada tubete de 1:100.000 tem 0,018 mg de epinefrina: 0,2 ÷ 0,018 = 11 tubetes no saudável e 0,04 ÷ 0,018 = 2 tubetes no cardiopata. O limite do cardiopata é menor porque a epinefrina acelera o coração e aumenta o gasto de oxigênio dele. Ex.: 0,2 ÷ 0,018 = 11 tubetes no paciente saudável; 0,04 ÷ 0,018 = 2 tubetes no cardiopata.", fonte: MAL },
  { t: "Não usar COX-2 seletivo", p: "O COX-2 seletivo corta a prostaciclina do vaso, que protege contra trombose, sem cortar o tromboxano da plaqueta. No cardiopata isso aumenta o risco de infarto e AVC. Ex.: paciente que colocou stent no coração há 1 ano: para dor pós-operatória, dipirona ou paracetamol em vez de celecoxibe.", fonte: RANG },
  { t: "a dipirona e o paracetamol são as escolhas mais seguras", p: "Os dois quase não interferem na plaqueta e não lesam o estômago, então não somam sangramento ao anticoagulante, ao contrário do AAS e dos AINEs. Ex.: paciente com rivaroxabana ou varfarina que fez uma extração: dor controlada com dipirona ou paracetamol, sem AINE.", fonte: RANG + '; ' + AND },
  { t: "A partir de 180 x 110 mmHg (não controlada)", p: "Com a pressão nesse nível, o medo e a dor do atendimento liberam adrenalina do próprio corpo e podem levar a AVC, infarto ou crise hipertensiva. Por isso o eletivo é adiado e o paciente vai ao médico antes. Ex.: paciente que esqueceu o remédio da pressão e chega com 182 x 112 mmHg: atendimento eletivo remarcado.", fonte: MAL },
  { t: "É o tratamento principal do abscesso", p: "O pus fica numa cavidade sem vasos, onde o antibiótico que vem pelo sangue quase não chega. Abrir e drenar tira as bactérias e a pressão (que causa a dor), e tratar a causa impede que o abscesso volte. Ex.: abscesso flutuante no fundo de vestíbulo do 36: incisão e drenagem aliviam a dor na hora, antes de qualquer antibiótico fazer efeito.", fonte: AND },

  /* ---------- Lote 2 ---------- */
  { t: "Na via endovenosa é 100%", p: "Na endovenosa o fármaco é colocado direto na circulação sistêmica: não há absorção e não há primeira passagem pelo fígado. Tudo o que foi injetado chega inalterado ao sangue. Ex.: 1 g de dipirona na veia = 1 g circulando; o mesmo 1 g por via oral perde uma parte na absorção e no fígado.", fonte: RANG },
  { t: "Em cerca de 5 meias-vidas", p: "A cada meia-vida a concentração plasmática cai pela metade: 100% → 50% → 25% → 12,5% → 6% → 3%. Depois de 5 meias-vidas sobra só uns 3%, que já quase não tem efeito. Ex.: a articaína, com meia-vida de uns 20 minutos, está praticamente fora do sangue em cerca de 1 hora e 40 minutos.", fonte: RANG },
  { t: "Ligação alta = o fármaco fica mais tempo no corpo", p: "O fármaco preso às proteínas plasmáticas (albumina) não é filtrado pelo rim nem entra no fígado com facilidade. Ele vai sendo solto aos poucos, como uma reserva, e por isso demora mais para ser eliminado. Ex.: a bupivacaína, muito ligada a proteínas, dura bem mais que a lidocaína.", fonte: RANG },
  { t: "depois disso aumentar a dose só aumenta a toxicidade", p: "Quando quase todos os receptores já estão ocupados, mais fármaco não tem onde agir para aumentar o efeito terapêutico. O excesso só se espalha para outros tecidos e aumenta os efeitos adversos. Ex.: dobrar a dose de dipirona além do recomendado não tira mais dor, mas aumenta o risco de efeito adverso.", fonte: RANG },
  { t: "Início mais lento", p: "O pKa da bupivacaína é alto (cerca de 8,1), mais longe do pH do tecido (7,4) que o da lidocaína. Então, no tecido, sobra menos forma não ionizada (a que atravessa a membrana do nervo), e o bloqueio demora mais a começar. Ex.: a lidocaína começa a agir em 2 a 3 minutos; a bupivacaína pode levar de 6 a 10 minutos.", fonte: MAL },
  { t: "Ela vem a 0,5%", p: "Como a bupivacaína é muito lipossolúvel e potente, uma concentração baixa já basta. Em concentração maior ela ficaria tóxica para o coração mais facilmente. Ex.: um tubete de bupivacaína 0,5% tem só 9 mg, contra 36 mg da lidocaína 2%.", fonte: MAL },
  { t: "concentração em % x 10 = mg/mL", p: "Porcentagem quer dizer gramas em 100 mL. 2% = 2 g em 100 mL = 2.000 mg em 100 mL = 20 mg em cada mL. Por isso multiplicar a % por 10 dá os mg/mL. Ex.: articaína 4% = 40 mg/mL; vezes 1,8 mL do tubete = 72 mg.", fonte: MAL },
  { t: "Calcule os DOIS limites e use o MENOR", p: "São dois riscos diferentes no mesmo tubete: o do anestésico (toxicidade no cérebro e no coração) e o da epinefrina (taquicardia, pressão alta). Qualquer um dos dois que for ultrapassado já faz mal, então vale o limite que chegar primeiro. Ex.: 60 kg com lidocaína 2% 1:100.000: lidocaína dá 7 tubetes, epinefrina dá 11; o máximo é 7.", fonte: AND },
  { t: "Vem a 3% SEM vasoconstritor", p: "A mepivacaína dilata pouco os vasos, então mesmo sem vasoconstritor ela fica mais tempo no local que a lidocaína pura. A concentração maior (3%) compensa a falta do vasoconstritor e dá uma anestesia curta, mas suficiente. Ex.: paciente com hipertensão no limite para um procedimento curto: mepivacaína 3% sem vasoconstritor, em dose controlada.", fonte: MAL },
  { t: "é nela que a superdosagem mais acontece", p: "A criança pesa pouco e a dose máxima dela é pequena, mas o tubete é o mesmo do adulto. Basta pouca coisa a mais para passar do limite, ainda mais quando se somam várias técnicas na mesma consulta. Ex.: criança de 15 kg com lidocaína 2%: 15 x 4,4 = 66 mg, menos de 2 tubetes.", fonte: MAL },
  { t: "azul de metileno intravenoso", p: "O azul de metileno ajuda as enzimas da hemácia a devolverem o ferro da hemoglobina do estado oxidado (metemoglobina) para o normal. Aí a hemoglobina volta a carregar oxigênio e a cianose melhora. Ex.: paciente arroxeado depois de muita prilocaína recebe azul de metileno na veia, no hospital, e a cor volta em minutos.", fonte: MAL },
  { t: "é essa forma que se liga ao canal de sódio", p: "A forma não ionizada (lipossolúvel) atravessa a membrana do nervo. Lá dentro, parte dela ganha um íon H+ de novo e vira a forma ionizada, que é a que encaixa no sítio dos canais de sódio pelo lado de dentro e impede a despolarização. Ex.: é como uma chave que entra desmontada pela porta e só é montada (ionizada) do lado de dentro para travar o canal.", fonte: MAL },
  { t: "Aumentar a dose ali não resolve", p: "No meio ácido a proporção continua desfavorável: a maior parte do anestésico extra também fica ionizada e presa fora do nervo. Só aumenta a quantidade que vai para o sangue e a toxicidade. Ex.: no 36 com abscesso, em vez de repetir 3 tubetes no local, faz-se o bloqueio do alveolar inferior longe do foco.", fonte: MAL },
  { t: "a felipressina é evitada em gestantes", p: "A felipressina é parecida com a vasopressina e a ocitocina, o hormônio que contrai o útero no parto. Em dose alta ela pode estimular contração uterina, então na gestante se prefere lidocaína com epinefrina. Ex.: gestante no 2º trimestre que precisa restaurar o 26: lidocaína 2% com epinefrina, não prilocaína com felipressina.", fonte: MAL },
  { t: "age mais no lado VENOSO", p: "A felipressina atua em receptores de vasopressina (V1), que contraem mais as vênulas do que as arteríolas. Como o sangue que chega pela arteríola continua passando, o campo continua sangrando. Ex.: numa cirurgia periodontal, a epinefrina deixa a mucosa pálida e o campo seco; com felipressina o campo sangra mais.", fonte: MAL },
  { t: "Dor e medo soltam muito mais adrenalina", p: "No estresse a suprarrenal joga no sangue uma quantidade de adrenalina muito maior que a de 1 ou 2 tubetes. Uma anestesia fraca, com o paciente sentindo dor, é mais perigosa para o coração do que a epinefrina do tubete. Ex.: cardiopata controlado anestesiado com 2 tubetes com epinefrina fica mais estável do que com anestésico sem vasoconstritor que não pega e dói.", fonte: MAL },
  { t: "1:50.000 é concentração maior", p: "1:50.000 é 1 g de epinefrina em 50.000 mL, ou seja, em metade do volume do 1:100.000. A mesma quantidade em menos líquido = o dobro da concentração: 0,02 mg/mL. Ex.: 1 tubete de 1:50.000 tem 0,036 mg, quase o limite inteiro do cardiopata (0,04 mg).", fonte: MAL },
  { t: "Hipertenso CONTROLADO pode receber", p: "Com a pressão arterial controlada, a pequena quantidade de epinefrina do tubete quase não muda a pressão, e a anestesia boa evita a dor, que subiria muito mais a pressão. O cuidado é a dose limitada, aspirar e injetar devagar. Ex.: Sr. Carlos, hipertenso com 135 x 85 mmHg tomando o remédio: restauração com 2 tubetes de lidocaína com epinefrina.", fonte: MAL },
  { t: "Paciente controlado pode ser atendido e pode receber epinefrina", p: "Quem está com a pressão arterial controlada tem margem para a pequena dose de epinefrina do tubete. O que sobe a pressão de verdade é a dor e o medo, e uma boa anestesia diminui os dois. Ex.: hipertenso controlado com 140 x 90 mmHg: atende, com dose limitada de epinefrina, aspiração e injeção lenta.", fonte: MAL },
  { t: "Trocar o vasoconstritor não resolve", p: "Na pressão muito alta o perigo vem do estresse e da dor do próprio procedimento, que soltam adrenalina do corpo. Tirar a epinefrina do tubete não tira esse estresse, e a anestesia mais fraca pode até piorar a dor. Ex.: paciente com 190 x 115 mmHg: mesmo com mepivacaína sem vasoconstritor, a extração eletiva é remarcada.", fonte: MAL },
  { t: "com a cicatrização e infecção", p: "Glicose alta atrapalha os neutrófilos (células de defesa) e a circulação nos vasos pequenos. Por isso a ferida do diabético descompensado demora a fechar e infecciona mais. Ex.: diabético com glicemia de 300 mg/dL que extrai um dente tem mais risco de alveolite e infecção.", fonte: MAL },
  { t: "Atender de manhã, depois do café e do remédio", p: "O diabético que tomou o remédio (ou a insulina) e não comeu pode ter hipoglicemia na cadeira, com suor, tremor e até desmaio. De manhã, alimentado e descansado, ele tolera melhor o estresse da consulta. Ex.: paciente com insulina marcado às 9h, depois de tomar o café normalmente; se chegar em jejum, oferece algo doce antes.", fonte: MAL },
  { t: "O 2º trimestre é a melhor época para tratamento eletivo", p: "No 1º trimestre o bebê está formando os órgãos, a fase mais sensível a remédios. No 3º trimestre a barriga grande deixa a gestante desconfortável na cadeira e, deitada de costas, o útero aperta a veia cava e a pressão cai. O 2º trimestre fica no meio, mais seguro. Ex.: gestante de 8 semanas com cárie sem dor: espera o 2º trimestre para restaurar; com dor ou infecção, atende na hora.", fonte: MAL },
  { t: "analgésico de escolha na gestante", p: "O paracetamol tem longa história de uso seguro na gravidez nas doses normais. Os AINEs, como o ibuprofeno, no 3º trimestre podem fechar antes da hora o ducto arterioso do bebê e diminuir o líquido amniótico. Ex.: gestante de 30 semanas com dor depois de um canal: paracetamol 500 a 750 mg de 6 em 6 horas, sem passar de 4 g por dia.", fonte: RANG + '; ' + "FDA, alerta sobre AINE a partir de 20 semanas de gestação (2020)" },
  { t: "pouca anti-inflamatória", p: "O paracetamol inibe a COX principalmente no sistema nervoso central. No tecido inflamado, cheio de peróxidos, ele perde a força e quase não reduz as prostaglandinas que causam o edema. Por isso tira dor e febre, mas não desincha. Ex.: depois de um terceiro molar, o paracetamol alivia a dor, mas não diminui o inchaço como o ibuprofeno ou a dexametasona.", fonte: RANG },
  { t: "pouca ação anti-inflamatória", p: "Dipirona e paracetamol agem mais na COX do sistema nervoso central do que no tecido inflamado, então reduzem pouco as prostaglandinas que fazem o edema. Tiram a dor e a febre, mas não o inchaço. Ex.: paciente com dor e face inchada depois de cirurgia: a dipirona alivia a dor, o edema precisa de anti-inflamatório ou corticoide.", fonte: RANG },
  { t: "Boa ação analgésica e antitérmica", p: "O paracetamol inibe a COX no cérebro, onde as prostaglandinas aumentam a sensação de dor e sobem o \"termostato\" do hipotálamo na febre. Bloqueando ali, a dor e a febre caem. Ex.: criança com febre e dor de dente até a consulta: paracetamol na dose por peso.", fonte: RANG },
  { t: "Usar pelo menor tempo possível", p: "Os efeitos adversos do AINE (estômago, rim, pressão arterial, sangramento) aumentam com o tempo de uso. Na dor da odontologia, que dura poucos dias, alguns dias bastam. Ex.: depois de uma extração, ibuprofeno por 2 a 3 dias, e não \"até acabar a caixa\".", fonte: AND },
  { t: "podem atrapalhar o efeito de anti-hipertensivos", p: "O rim usa prostaglandinas para manter o fluxo de sangue e eliminar sódio. O AINE corta essas prostaglandinas, o rim segura sódio e água, e a pressão arterial sobe, anulando parte do remédio da pressão. Ex.: hipertenso que toma losartana e usa diclofenaco por uma semana pode ver a pressão subir.", fonte: RANG },
  { t: "meia-vida longa: tomado de 12 em 12 horas", p: "Com meia-vida de cerca de 14 horas, a concentração plasmática do naproxeno cai devagar, e uma dose segura o efeito por bastante tempo. Por isso o intervalo é maior que o do ibuprofeno. Ex.: ibuprofeno de 6 em 6 ou de 8 em 8 horas; naproxeno de 12 em 12 horas.", fonte: RANG },
  { t: "de forma irreversível", p: "O AAS acetila a COX da plaqueta e a estraga para sempre. A plaqueta não tem núcleo, então não consegue fabricar COX nova: fica sem agregar até ser trocada, em 7 a 10 dias. Ex.: paciente que toma AAS e vai fazer extração: o sangramento fica maior por dias, mesmo depois de parar o comprimido.", fonte: RANG },
  { t: "O AAS é antiagregante", p: "O AAS bloqueia o tromboxano da plaqueta para sempre (COX-1 acetilada), então as plaquetas não grudam para fechar o vaso. Somado à varfarina, que já diminui a coagulação, o sangramento depois de uma extração fica muito maior. Ex.: paciente com varfarina que toma AAS para dor depois de extrair um dente volta sangrando à noite.", fonte: RANG },
  { t: "Antibiótico não é anti-inflamatório", p: "O antibiótico só mata ou para bactérias. O edema depois de uma cirurgia é inflamação sem infecção, feita pelas prostaglandinas e leucotrienos do próprio corpo, e o antibiótico não mexe nisso. Ex.: dar amoxicilina \"para não inchar\" depois de um terceiro molar não reduz o edema; a dexametasona antes, sim.", fonte: AND },
  { t: "Esperar o edema aparecer para medicar", p: "O corticoide age impedindo a produção de novas prostaglandinas e leucotrienos, mas não desfaz os que já foram feitos. Se ele só chega depois que a cascata começou, o inchaço já está montado. Ex.: dexametasona 1 hora antes do terceiro molar reduz o edema do dia seguinte; dada só no dia seguinte, ajuda bem menos.", fonte: AND },
  { t: "Não tem ação anti-inflamatória", p: "O benzodiazepínico age no receptor GABA-A do sistema nervoso central, acalmando o cérebro. Ele não mexe na COX nem na fosfolipase A2, então não reduz o edema nem a inflamação. Ex.: midazolam deixa o paciente calmo para a cirurgia, mas o inchaço depois depende da dexametasona ou do AINE.", fonte: RANG },
  { t: "corticoide não é ansiolítico", p: "O corticoide age na inflamação (fosfolipase A2), não no receptor GABA-A do cérebro. Quem acalma o paciente é o benzodiazepínico. Ex.: para paciente ansioso e cirurgia de terceiro molar: midazolam para a ansiedade e dexametasona para o edema, cada um com seu papel.", fonte: RANG },
  { t: "achar que corticoide é controlado", p: "Os corticoides não causam dependência psíquica nem estão nas listas de psicotrópicos da Portaria 344/1998. Por isso vão em receita simples, sem retenção na farmácia. Ex.: dexametasona 8 mg para o terceiro molar vai na receita comum; o diazepam do mesmo paciente vai na receita azul.", fonte: "Portaria SVS/MS 344/1998" },
  { t: "Prescrição em receita simples", p: "Analgésicos, AINEs e corticoides não causam dependência e não estão nas listas de controle da Portaria 344/1998, nem são antimicrobianos. Por isso a receita comum basta. Ex.: receita simples com dipirona e ibuprofeno; a amoxicilina do mesmo paciente vai em receita de 2 vias.", fonte: "Portaria SVS/MS 344/1998" + '; ' + "ANVISA, RDC 20/2011" },
  { t: "pode prescrever pelo nome genérico", p: "A lei dos genéricos permite (e no SUS exige) a prescrição pelo nome do princípio ativo. O que importa para o paciente tomar certo é o fármaco, a concentração e a posologia, não a marca. Ex.: \"Amoxicilina 500 mg\" na receita vale para qualquer marca ou genérico na farmácia.", fonte: "Lei 9.787/1999 (Lei dos Genéricos)" },
  { t: "Receita sem posologia está incompleta", p: "Sem dizer dose, intervalo e por quantos dias, o paciente pode tomar de menos (o remédio não funciona e, no antibiótico, favorece resistência) ou de mais (toxicidade). A posologia é o que transforma o nome do remédio em tratamento. Ex.: \"Paracetamol, quando necessário\" não diz quanto tomar; o certo é \"Paracetamol 750 mg, 1 comprimido de 6 em 6 horas, se dor, por até 3 dias\".", fonte: AND },
  { t: "favorece resistência", p: "Cada vez que um antibiótico é usado sem necessidade ou sem tratar a causa, as bactérias mais fortes sobrevivem e se multiplicam. Com o tempo, a infecção passa a não responder mais àquele antibiótico. Ex.: paciente que toma amoxicilina toda vez que o dente com abscesso incha, sem tratar o canal, acaba com bactérias que a amoxicilina não mata.", fonte: ANV },
  { t: "em procedimento que manipula gengiva, região periapical ou perfura a mucosa", p: "São esses procedimentos que jogam bactérias da boca no sangue (bacteremia) em quantidade maior. Anestesia em tecido sadio, radiografia ou ajuste de aparelho quase não fazem isso. Ex.: paciente com prótese valvar faz profilaxia para raspagem subgengival, mas não para tirar radiografia.", fonte: AHA },
  { t: "Idade sozinha não indica", p: "A endocardite depende de uma válvula ou estrutura do coração já alterada onde a bactéria possa grudar. Ser idoso não cria esse ponto; o que define é a condição do coração. Ex.: idoso de 80 anos saudável não faz profilaxia; jovem de 25 anos com prótese de válvula faz.", fonte: AHA },
  { t: "ainda pode receber cefalexina 2 g", p: "A reação cruzada entre penicilina e cefalosporinas é baixa, principalmente em quem teve só reação leve. Quem teve anafilaxia, angioedema ou urticária fica de fora, porque aí qualquer risco é grave demais. Ex.: paciente com prótese valvar que teve só uma mancha leve com amoxicilina há anos pode receber cefalexina 2 g antes; quem fechou a garganta, azitromicina.", fonte: AHA },
  { t: "o clavulanato quase não tem ação antibacteriana sozinho", p: "O clavulanato é um \"inibidor suicida\": ele se gruda na betalactamase e a inativa, mas quase não se liga às enzimas que montam a parede da bactéria. O trabalho de matar a bactéria é da amoxicilina. Ex.: o clavulanato é o escudo e a amoxicilina é a espada; o escudo sozinho não ganha a briga.", fonte: RANG },
  { t: "saiu só da PROFILAXIA de endocardite", p: "Na profilaxia muita gente sem infecção nenhuma recebe a dose, então um efeito adverso grave como a colite pesa mais que o benefício. No tratamento de uma infecção que já existe, no alérgico à penicilina, o benefício da clindamicina ainda compensa. Ex.: alérgico à penicilina com abscesso e celulite pode tratar com clindamicina; o mesmo paciente, para profilaxia antes de uma extração, recebe azitromicina.", fonte: AHA },
  { t: "Alérgico a uma = alérgico a todas", p: "Todas as penicilinas têm o mesmo núcleo, com o anel betalactâmico, e é esse núcleo que o sistema imune reconhece. Trocar uma penicilina por outra não muda o alvo da alergia. Ex.: quem teve anafilaxia com Benzetacil não pode tomar amoxicilina nem amoxicilina com clavulanato.", fonte: AND },
  { t: "Na anafilaxia é o remédio de emergência", p: "A epinefrina contrai os vasos (alfa-1), segurando a pressão e o inchaço da garganta, e abre os brônquios (beta-2). Na anafilaxia ela age em minutos sobre tudo o que mata o paciente. Ex.: paciente que fica com a garganta fechando e a pressão caindo depois de um remédio recebe epinefrina 0,5 mg na coxa e o socorro é chamado.", fonte: "Diretriz de anafilaxia da WAO (World Allergy Organization, 2020)" },
  { t: "epinefrina por via intramuscular", p: "No músculo da coxa a epinefrina é absorvida rápido e de forma previsível, sem o risco de arritmia da injeção direta na veia. É a via mais segura para quem não está num hospital. Ex.: adulto em anafilaxia no consultório: 0,5 mg (0,5 mL da solução 1 mg/mL) no músculo da coxa, podendo repetir em 5 a 15 minutos.", fonte: "Diretriz de anafilaxia da WAO (World Allergy Organization, 2020)" },
  { t: "alergia verdadeira a amida é rara", p: "As amidas são metabolizadas no fígado e não formam PABA, a substância que dá alergia nos ésteres. A maioria das \"alergias a anestésico\" é na verdade desmaio, ansiedade ou reação à epinefrina. Ex.: paciente que diz ser alérgico a anestésico porque o coração disparou na última consulta provavelmente teve efeito da epinefrina, não alergia.", fonte: MAL },
  { t: "é a técnica que mais causa", p: "No PSA a agulha passa atrás da tuberosidade, numa região cheia de veias (o plexo venoso pterigóideo). Se ela vai fundo demais, fura essas veias e o sangue se espalha pela bochecha. Ex.: logo depois do PSA a bochecha do paciente incha e fica arroxeada nos dias seguintes.", fonte: MAL },
  { t: "Técnica que mais dá hematoma", p: "A agulha do PSA trabalha perto do plexo venoso pterigóideo, uma rede de veias atrás da maxila. Agulha profunda demais fura essas veias e forma o hematoma. Ex.: usar agulha curta e não enterrar até o fim diminui a chance de hematoma no PSA.", fonte: MAL },
  { t: "gelo nas primeiras horas", p: "O frio contrai os vasos, então menos sangue sai da veia furada e o inchaço fica menor. Depois das primeiras 24 horas, o calor ajuda a reabsorver o sangue. Ex.: depois de um hematoma no PSA: compressão firme na hora e gelo por fora da bochecha, 20 minutos sim, 20 não, no primeiro dia.", fonte: MAL },
  { t: "o nervo mais atingido nas parestesias", p: "Na altura da língula, o nervo lingual passa bem no caminho da agulha do bloqueio do alveolar inferior e, em cerca de 1/3 das pessoas, é unifascicular (um feixe só de fibras, sem tecido de proteção em volta). A agulha que encosta nele, o hematoma ou o próprio anestésico atingem o nervo inteiro de uma vez, e a recuperação demora. Estudos de notificações também mostram mais parestesia com as soluções a 4% (articaína e prilocaína), pela toxicidade do anestésico concentrado sobre o nervo. Ex.: três semanas depois de um bloqueio, o paciente ainda sente metade da língua formigando.", fonte: 'Pogrel & Thamby, JADA 2000;131:901-7; Pogrel e cols., JADA 2003;134:195-9; Haas & Lennon, J Can Dent Assoc 1995;61:319-30; ' + MAL },
  { t: "manter a boca aberta 1 a 2 minutos", p: "Com a boca aberta o côndilo vai para a frente e o nervo fica mais perto do ponto onde o anestésico foi depositado. Manter assim dá tempo da solução se espalhar pelo tronco do V3. Ex.: depois de injetar o tubete do Gow-Gates, o paciente fica de boca aberta, apoiado, por 1 a 2 minutos antes de fechar.", fonte: MAL },
  { t: "com menos aspiração positiva", p: "No colo do côndilo, alvo do Gow-Gates, há menos vasos grandes do que no espaço pterigomandibular do bloqueio convencional. Por isso a agulha cai menos dentro de vaso. Ex.: a aspiração positiva no Gow-Gates fica em torno de 2%, contra cerca de 10 a 15% no alveolar inferior convencional.", fonte: MAL },
  { t: "e na criança mais ainda", p: "O osso da criança é menos mineralizado e mais poroso que o do adulto, então o anestésico passa ainda mais fácil até o ápice. Por isso a infiltração funciona até em dentes inferiores de criança pequena. Ex.: pulpotomia no 55 de uma criança de 8 anos com uma infiltração vestibular.", fonte: MAL },
  { t: "ela falha nos posteriores", p: "Nos molares inferiores do adulto a cortical vestibular é grossa e compacta, e o anestésico injetado no fundo de vestíbulo não atravessa até o ápice. Na frente da mandíbula o osso é mais fino e a infiltração às vezes funciona. Ex.: infiltrar no vestíbulo do 46 de um adulto costuma não anestesiar a polpa; precisa do bloqueio do alveolar inferior.", fonte: MAL },
  { t: "é a injeção que mais dói", p: "A mucosa do palato é grudada no osso, sem espaço para o líquido; qualquer volume estica o tecido, e a papila é muito inervada. Por isso se injeta pouco e devagar. Ex.: pressionar com o cabo do espelho ao lado da papila antes e durante a picada diminui a dor.", fonte: MAL },
  { t: "a injeção dói, fazer devagar e com pouco volume", p: "A mucosa do palato é firme e presa ao osso: o líquido não tem para onde ir e estica o tecido, o que dói. Injetando pouco e devagar, a pressão não sobe de uma vez. Ex.: no palatino maior bastam 0,25 a 0,5 mL injetados em uns 30 segundos.", fonte: MAL },
  { t: "Risco citado nos slides: necrose da papila", p: "A papila tem pouca irrigação. Injetar ali sob pressão, com vasoconstritor, pode deixar o tecido sem sangue por tempo demais e ele morre. Ex.: depois de uma intrapapilar forçada, a papila fica branca e depois escurece e cai, deixando um \"buraco\" entre os dentes.", fonte: MAL },
  { t: "injetando sob pressão no ligamento periodontal", p: "O espaço do ligamento periodontal é muito estreito, então o anestésico só entra com pressão. Daí ele passa pelo osso esponjoso até o ápice e anestesia a polpa só daquele dente, sem bloqueio regional. Ex.: tratar um único dente inferior sem deixar a língua e o lábio dormentes, como faria o alveolar inferior.", fonte: MAL },
  { t: "Dói no início e é técnica de exceção", p: "A agulha entra direto na polpa exposta e inflamada, que é muito sensível. Por isso só se usa quando as outras técnicas falharam. Ex.: pulpite aguda no 46 em que o bloqueio e a intraligamentar não pegaram: a intrapulpar resolve para abrir o canal.", fonte: MAL },
  { t: "bloqueio só superficial, de ação curta", p: "O anestésico tópico só penetra uns 2 a 3 mm na mucosa e é absorvido rápido pelos vasos dela. Serve para tirar a dor da picada, não para anestesiar o dente. Ex.: passar o tópico 1 a 2 minutos antes da agulha no fundo de vestíbulo.", fonte: MAL },
  { t: "para trás, para cima e para dentro", p: "Esse é o caminho da superfície de trás da maxila (a tuberosidade), onde os nervos alveolares superiores posteriores entram no osso. A agulha acompanha a curva do osso para depositar o anestésico junto deles. Ex.: no PSA, a seringa começa apoiada na comissura e a agulha entra acima do 2º molar seguindo essas três direções.", fonte: MAL },
  { t: "Agulha curta pela vestibular acima do 2º molar", p: "O alvo do PSA é raso e fica perto do plexo venoso pterigóideo. Com agulha curta fica difícil ir fundo demais, o que diminui o risco de hematoma. Ex.: agulha curta (cerca de 20 mm), inserida uns 16 mm em adulto de tamanho médio.", fonte: MAL },
  { t: "Pede anestesia do dente E dos tecidos de volta", p: "O dente é inervado por um nervo e a gengiva, o periósteo e a mucosa de volta muitas vezes por outros. Para extrair, é preciso anestesiar todos os que serão tocados pelo fórceps e pela alavanca. Ex.: extrair o 46: alveolar inferior (dente), lingual (gengiva lingual) e bucal (gengiva vestibular).", fonte: MAL },
  { t: "com a polpa inflamada (pulpite) a anestesia falha mais", p: "Na pulpite o tecido fica ácido, o anestésico fica mais ionizado e entra menos no nervo. Além disso, os nervos inflamados ficam mais sensíveis e precisam de mais bloqueio para parar. Ex.: paciente com dor forte no 36 que, mesmo com lábio dormente, sente dor ao abrir o dente.", fonte: MAL },
  { t: "pode acelerar o coração", p: "A acetilcolina, pelo nervo vago, age em receptores muscarínicos do coração e freia os batimentos. A atropina bloqueia esse freio, e o coração bate mais rápido. Ex.: a atropina é usada em emergência justamente quando o coração está lento demais.", fonte: RANG },
  { t: "conferido perto do dia", p: "O INR varia com alimentação, outros remédios e doenças. Um valor de semanas atrás pode não ser o de hoje, e é o de perto da cirurgia que diz se o sangramento será controlável. Ex.: paciente com varfarina faz o INR na véspera da extração; se estiver na faixa do médico, extrai sem parar o remédio.", fonte: AND },
  { t: "início rápido e curta duração", p: "O midazolam é bem absorvido, entra rápido no cérebro e é metabolizado depressa pelo fígado. Assim faz efeito em uns 30 minutos e passa em poucas horas. Ex.: midazolam 7,5 mg às 13h30 para uma cirurgia às 14h; à noite o paciente já está bem desperto.", fonte: AND },
  { t: "Benzodiazepínico de ação mais longa que o midazolam", p: "O diazepam é transformado no fígado em um metabólito que também age e demora muito a sair do corpo. Por isso a sonolência pode durar até o dia seguinte. Ex.: paciente que toma diazepam antes da consulta pode ficar sonolento até a noite e não deve trabalhar com máquina.", fonte: RANG },
  { t: "mais cloreto entra", p: "O cloreto tem carga negativa. Entrando no neurônio, deixa o interior mais negativo (hiperpolarização), e o neurônio fica mais difícil de disparar: o cérebro \"freia\" e vem a calma e o sono. Ex.: é por isso que o benzodiazepínico dá sonolência e, em dose alta, pode diminuir a respiração.", fonte: RANG },
  { t: "supressão da suprarrenal é risco do uso prolongado", p: "Quando o corpo recebe corticoide de fora todos os dias por semanas, a hipófise para de mandar a suprarrenal trabalhar e ela \"atrofia\". Isso precisa de tempo; uma dose isolada não chega a desligar o eixo. Ex.: paciente que toma prednisona há 6 meses precisa de cuidado na cirurgia; quem toma 1 dose de dexametasona, não.", fonte: AND },
  { t: "A colite por C. difficile (diarreia grave)", p: "O antibiótico mata as bactérias boas do intestino. A Clostridioides difficile, que resiste a ele, cresce sem concorrência e solta toxinas que inflamam o intestino grosso. Ex.: paciente que toma clindamicina e, dias depois, tem diarreia com muitas evacuações, febre e dor na barriga.", fonte: AHA },
  { t: "depressão respiratória", p: "Os opioides agem em receptores do tronco cerebral que controlam a respiração e deixam o cérebro menos sensível ao CO2 acumulado. A respiração fica lenta e rasa, e em dose alta pode parar. Ex.: paciente que mistura codeína com álcool ou benzodiazepínico tem mais risco de respirar pouco.", fonte: RANG },
  { t: "é anestesiado no recuo da agulha", p: "O nervo lingual corre no mesmo espaço pterigomandibular, um pouco à frente e por dentro do alveolar inferior, a cerca de 1 cm. Recuando a agulha até a metade, ela fica perto do lingual, e um pouco de anestésico já basta. Ex.: depois de injetar 1,5 mL no alveolar inferior, recua uns 10 mm e injeta 0,3 mL para o lingual.", fonte: MAL },
  { t: "Lingual: no recuo da agulha", p: "O nervo lingual corre no mesmo espaço pterigomandibular, um pouco à frente e por dentro do alveolar inferior, a cerca de 1 cm. Recuando a agulha até a metade, ela fica perto do lingual, e um pouco de anestésico já basta. Ex.: depois de injetar 1,5 mL no alveolar inferior, recua uns 10 mm e injeta 0,3 mL para o lingual.", fonte: MAL },
  { t: "vai junto com o alveolar inferior, no recuo da agulha", p: "O nervo lingual corre no mesmo espaço pterigomandibular, um pouco à frente e por dentro do alveolar inferior, a cerca de 1 cm. Recuando a agulha até a metade, ela fica perto do lingual, e um pouco de anestésico já basta. Ex.: depois de injetar 1,5 mL no alveolar inferior, recua uns 10 mm e injeta 0,3 mL para o lingual.", fonte: MAL },
  { t: "fundo de vestíbulo sobre o 1º pré-molar", p: "O forame infraorbital fica mais ou menos em linha vertical com os pré-molares. Entrando sobre o 1º pré-molar, a agulha sobe paralela ao longo eixo do dente direto para o forame, guiada pelo dedo. Ex.: dedo apalpando o forame embaixo da borda da órbita e agulha curta entrando no vestíbulo do 14 em direção ao dedo.", fonte: MAL },
  { t: "de 6 em 6 horas, por curto período", p: "O efeito analgésico da dipirona dura cerca de 4 a 6 horas, então esse intervalo mantém a dor controlada. Curto período porque a dor da extração dura poucos dias e assim se reduz o risco de efeito adverso. Ex.: dipirona 1 g de 6 em 6 horas por 2 a 3 dias depois da extração.", fonte: AND },
  { t: "O paracetamol também serviria, em dose moderada", p: "O paracetamol quase não mexe na plaqueta, mas em dose alta e todos os dias pode aumentar o efeito da varfarina e subir o INR. Por isso, no paciente anticoagulado, dose moderada e poucos dias. Ex.: paciente com varfarina usando paracetamol 750 mg de 8 em 8 horas por 3 dias depois da extração.", fonte: RANG + '; ' + AND },
  { t: "Interrupção REVERSÍVEL da condução", p: "O anestésico se encaixa nos canais de sódio sem destruí-los. Com o tempo, a circulação leva o anestésico embora (absorção), o fígado faz a biotransformação, os canais voltam a funcionar e o impulso nervoso passa de novo. Ex.: depois de 2 a 3 horas o lábio \"acorda\" sozinho, sem nenhuma sequela.", fonte: MAL },
  { t: "sem perda de consciência", p: "O anestésico local é colocado perto do nervo periférico e só bloqueia ali. A quantidade que chega ao cérebro é pequena demais para tirar a consciência, diferente da anestesia geral. Ex.: o paciente fica acordado e conversando durante a extração, só sem dor naquela região.", fonte: MAL },
  { t: "Inerva os 2/3 anteriores da língua", p: "A língua tem nervos diferentes na frente e atrás porque se forma de partes diferentes no embrião. Nos 2/3 anteriores, o tato, a dor e a temperatura vêm pelo nervo lingual (ramo do V3), e o paladar viaja junto dele pela corda do tímpano, que é do nervo facial (VII). O 1/3 posterior é do glossofaríngeo (IX). Por isso o bloqueio do lingual deixa a ponta da língua dormente e pode mudar o gosto, mas não a parte de trás. Ex.: depois do bloqueio do alveolar inferior com o lingual, o paciente morde a ponta da língua sem sentir, mas continua sentindo a base da língua ao engolir.", fonte: "Gray's Anatomy" + '; ' + "Netter, Atlas de Anatomia Humana" },
  /* ---------- Lote 3 ---------- */
  { t: "nenhum anestésico tem toxicidade zero", p: "Todo anestésico local que chega ao sangue em concentração alta age também nos canais de sódio do cérebro e do coração. Por isso toda amida, inclusive a bupivacaína, tem dose máxima: o que muda de um para outro é a margem, não a existência de toxicidade. Ex.: a bupivacaína, por ser muito potente, é a mais tóxica para o coração se cair no vaso, mesmo com tubete de só 9 mg.", fonte: MAL },
  { t: "no consultório a rotina é oral e anestesia local, não EV", p: "A via endovenosa exige acesso venoso, monitorização e preparo para emergência, porque o efeito é imediato e um erro de dose não tem como voltar. No consultório odontológico comum, a via oral e a anestesia local resolvem quase tudo com mais segurança. Ex.: a sedação do paciente ansioso é feita com midazolam por via oral, e não na veia.", fonte: RANG },
  { t: "avança 25 mm até o espaço pterigomandibular", p: "Na Vazirani-Akinosi a agulha entra paralela ao plano oclusal, sem tocar osso como referência. Os 25 mm são, no adulto médio, a distância do ponto de entrada até o espaço pterigomandibular, onde passam o alveolar inferior e o lingual. Ex.: em adulto pequeno ou criança a profundidade é menor, para não ir além do ramo e chegar à parótida.", fonte: MAL },
  { t: "agulha CURTA, calibre 27 ou 30", p: "A agulha curta diminui o risco de ir fundo demais no PSA e furar o plexo venoso pterigóideo (hematoma). Agulhas mais grossas entortam menos e mostram melhor o sangue na aspiração; as finíssimas quase não diminuem a dor da picada. Ex.: no PSA de um adulto, a agulha curta entra uns 16 mm, e não até o canhão.", fonte: MAL },
  { t: "Pode estar ausente em parte das pessoas", p: "A anatomia dos nervos alveolares superiores varia de pessoa para pessoa. Quando o alveolar superior médio não existe, os pré-molares e a raiz mesiovestibular recebem fibras do posterior e do anterior, e por isso às vezes um único bloqueio não basta. Ex.: paciente em que o infraorbitário pegou os incisivos, mas o 15 continua sensível: complementa com infiltração no pré-molar.", fonte: MAL },
  { t: "em concentração de 4%", p: "A articaína é inativada rápido no sangue pelas esterases (por causa do grupo éster extra), então pode ser usada mais concentrada com boa margem. O anel tiofeno a deixa lipossolúvel, e ela se espalha bem pelo osso. Ex.: muitos dentistas usam articaína 4% em infiltração vestibular no 1º molar inferior de adulto como complemento do bloqueio.", fonte: MAL },
  { t: "limitar a epinefrina a 0,04 mg por sessão", p: "A epinefrina aumenta a frequência e a força do coração (receptor beta-1) e o consumo de oxigênio dele. No cardiopata a reserva é pequena, então o limite cai para 0,04 mg, o equivalente a cerca de 2 tubetes de 1:100.000. Ex.: cardiopata compensado: 2 tubetes de lidocaína 2% 1:100.000 (0,036 mg), com aspiração e injeção lenta.", fonte: MAL },
  { t: "medida duas vezes com o paciente em repouso", p: "A pressão arterial sobe com o medo, a pressa e a conversa logo que o paciente senta (efeito do jaleco branco). Medir em repouso e repetir mostra se a pressão está alta de verdade antes de cancelar ou fazer o procedimento. Ex.: paciente chega correndo com 170 x 105 mmHg; depois de 5 minutos sentado e calmo, a segunda medida dá 145 x 90 mmHg.", fonte: MAL },
  { t: "ou doxiciclina (100 mg)", p: "A doxiciclina é de outra família (tetraciclina), sem reação cruzada com a penicilina, e cobre as bactérias da boca que causam endocardite. Por isso entrou como alternativa para o alérgico na diretriz de 2021. Ex.: paciente com prótese valvar, alérgico à penicilina e com intolerância a macrolídeo: doxiciclina 100 mg antes da raspagem (não em criança pequena nem gestante).", fonte: AHA },
  { t: "induzida na inflamação", p: "A COX-1 é fabricada o tempo todo, para manter funções normais (estômago, rim, plaqueta). A COX-2 quase não existe no tecido normal; ela é produzida quando citocinas da inflamação (como IL-1 e TNF) mandam a célula fabricá-la, e aí produz as prostaglandinas da dor, do edema e da febre. Ex.: depois de extrair um terceiro molar, a COX-2 do local aumenta muito nas primeiras horas, e é por isso que a dor e o inchaço crescem.", fonte: RANG },
  { t: "Fosfolipase A2 é o alvo do corticoide", p: "O corticoide entra na célula, se liga a um receptor e manda fabricar a anexina-1 (lipocortina), que inibe a fosfolipase A2. Sem ela não sai ácido araquidônico da membrana, e faltam tanto prostaglandinas quanto leucotrienos. Ex.: por agir lá no início da cascata, a dexametasona diminui mais o edema do terceiro molar que o ibuprofeno.", fonte: RANG },
  { t: "(via anexinas/lipocortinas)", p: "O corticoide não inibe a fosfolipase A2 diretamente: ele se liga a um receptor dentro da célula e manda fabricar anexinas (lipocortinas), que é que freiam a enzima. Por isso o efeito demora algumas horas para aparecer. Ex.: é um dos motivos para dar a dexametasona cerca de 1 hora antes da cirurgia, e não na hora.", fonte: RANG },
  { t: "Ele não aumenta a potência do sal", p: "A potência depende da molécula do anestésico, principalmente de quanto ela é lipossolúvel e se liga ao canal de sódio. O vasoconstritor só segura o anestésico mais tempo no local (absorção mais lenta): muda a duração e a toxicidade, não a força. Ex.: lidocaína 2% com ou sem epinefrina bloqueia o nervo com a mesma força; a diferença é quanto tempo dura.", fonte: MAL },
  { t: "a dose não substitui a aspiração", p: "Mesmo uma dose pequena, se for injetada dentro do vaso, chega de uma vez ao coração e ao cérebro em concentração alta. O limite de dose protege contra o total da sessão; a aspiração protege contra o caminho errado. Ex.: meio tubete com epinefrina injetado direto numa veia já pode dar taquicardia e palpitação no cardiopata.", fonte: MAL },
  { t: "agulha curta, 2 a 3 mm", p: "Na infiltração o objetivo é deixar o anestésico perto do ápice, logo acima do periósteo da maxila, que é fino. Não precisa entrar fundo: o osso poroso deixa a solução passar até as terminações do dente. Ex.: para restaurar o 14, a agulha entra no fundo de vestíbulo só alguns milímetros e injeta-se 0,6 a 1,0 mL.", fonte: MAL },
  { t: "útil em cirurgia", p: "Na intrasseptal o anestésico vai direto no osso entre os dentes, junto com o vasoconstritor. Dá anestesia de osso e gengiva da região com pouco volume e ainda diminui o sangramento do campo, o que ajuda na cirurgia periodontal. Ex.: numa cirurgia de gengiva entre o 45 e o 46, a intrasseptal complementa o bloqueio e deixa o campo mais seco.", fonte: MAL },
  { t: "cerca de 30 min", p: "O midazolam por via oral leva cerca de 30 minutos para ser absorvido e chegar ao pico no cérebro. Dado nesse horário, o paciente está calmo justamente quando a consulta começa. Ex.: consulta às 15h: midazolam 7,5 mg às 14h30, já com o acompanhante junto.", fonte: AND },
  { t: "reduz edema, trismo e dor", p: "O corticoide corta na origem as prostaglandinas e os leucotrienos, que deixam os vasos permeáveis (edema) e sensibilizam os nervos (dor). Com menos edema em volta dos músculos, o paciente também abre melhor a boca (menos trismo). Ex.: paciente que tomou dexametasona antes de tirar o 38 e o 48 tem o rosto bem menos inchado no 2º dia que outro que não tomou.", fonte: AND },
  { t: "protege o estômago e ajuda o rim", p: "No estômago, as prostaglandinas aumentam o muco e o bicarbonato e diminuem o ácido. No rim, elas dilatam os vasos e mantêm o fluxo de sangue quando a pressão cai. Por isso inibir a COX-1 machuca o estômago e pode atrapalhar o rim. Ex.: idoso desidratado que toma diclofenaco por vários dias pode ter piora da função do rim.", fonte: RANG },
  { t: "constitutiva (protege estômago, plaqueta, rim)", p: "Constitutiva quer dizer que a COX-1 está sempre lá, fabricando as prostaglandinas que protegem a mucosa do estômago, o tromboxano da plaqueta e as que mantêm o fluxo de sangue no rim. Bloqueá-la mexe nessas três funções. Ex.: o ibuprofeno, que bloqueia a COX-1, pode dar dor no estômago e aumentar o sangramento depois de uma extração.", fonte: RANG },
  { t: "os AINEs só as prostaglandinas", p: "O AINE bloqueia só a COX. O ácido araquidônico continua sendo liberado e segue livre pela outra via, a da lipoxigenase, que faz leucotrienos; às vezes sobra até mais para ela. Ex.: em algumas pessoas com asma, o AAS e outros AINEs desviam o ácido araquidônico para os leucotrienos e desencadeiam crise de asma.", fonte: RANG },
  { t: "reação adversa rara associada à dipirona", p: "Em pouquíssimas pessoas a dipirona provoca uma reação imunológica contra os neutrófilos, que caem muito. É rara e por isso a ANVISA manteve a dipirona no Brasil, enquanto alguns países a proibiram. Ex.: paciente que toma dipirona e aparece com febre, dor de garganta e feridas na boca deve parar o remédio e fazer hemograma.", fonte: RANG + '; ' + "ANVISA, Painel Internacional de Avaliação da Segurança da Dipirona (2001)" },
  { t: "escolha segura no paciente com varfarina", p: "A dipirona inibe a COX de forma fraca e reversível, então quase não mexe na plaqueta, e não lesa o estômago como os AINEs. Não soma sangramento ao anticoagulante. Ex.: idoso com varfarina e INR controlado, depois de uma extração: dipirona 1 g de 6 em 6 horas por 2 a 3 dias.", fonte: AND },
  { t: "pequeno e reversível na plaqueta", p: "A dipirona se liga à COX da plaqueta de forma fraca e solta quando sai do sangue; o AAS, ao contrário, estraga a COX para sempre. Assim, a plaqueta volta a funcionar algumas horas depois da dose e o sangramento quase não muda. Ex.: paciente com varfarina pode usar dipirona depois da extração, mas não AAS.", fonte: RANG },
  { t: "acima da dose máxima diária (4 g no adulto)", p: "Uma pequena parte do paracetamol vira NAPQI, que a glutationa do fígado neutraliza. Acima de uns 4 g por dia a glutationa acaba, o NAPQI sobra e destrói as células do fígado. Ex.: paracetamol 750 mg de 4 em 4 horas o dia todo dá 4,5 g e já passou do limite.", fonte: RANG },
  { t: "COX-2 seletivos (celecoxibe) aumentam o risco", p: "O celecoxibe bloqueia a prostaciclina dos vasos (feita muito pela COX-2), que dilata e impede a plaqueta de grudar, mas não mexe no tromboxano da plaqueta (COX-1), que favorece o trombo. O equilíbrio pende para a trombose: infarto e AVC. Ex.: paciente que colocou stent no coração há 1 ano não recebe celecoxibe para dor pós-operatória.", fonte: RANG },
  { t: "agride menos o estômago, mas AUMENTA", p: "Poupando a COX-1, o celecoxibe mantém as prostaglandinas que protegem a mucosa do estômago. Mas, ao bloquear a prostaciclina dos vasos sem bloquear o tromboxano da plaqueta, aumenta o risco de trombose. Ex.: bom para quem tem gastrite e coração saudável; ruim para o cardiopata.", fonte: RANG },
  { t: "inibidores seletivos da COX-2 aumentam o risco", p: "Eles cortam a prostaciclina dos vasos, que protege contra trombose, e deixam o tromboxano da plaqueta funcionando. Sem o contrapeso, cresce o risco de infarto e AVC. Ex.: o rofecoxibe (Vioxx) saiu do mercado em 2004 por esse motivo.", fonte: RANG },
  { t: "poupam mais o estômago, mas têm risco cardiovascular", p: "Os COX-2 seletivos deixam a COX-1 do estômago trabalhar, então a mucosa continua protegida. O preço é o desequilíbrio entre prostaciclina e tromboxano, que favorece trombose. Ex.: celecoxibe por poucos dias em quem tem gastrite e coração saudável; dipirona ou paracetamol no cardiopata.", fonte: RANG },
  { t: "a COX-2 seletiva aumenta trombose e infarto", p: "Ela bloqueia a prostaciclina dos vasos (antiagregante e vasodilatadora) sem bloquear o tromboxano da plaqueta (pró-agregante). Fica o lado da coagulação sem contrapeso. Ex.: paciente com histórico de infarto não recebe celecoxibe, mesmo tendo gastrite.", fonte: RANG },
  { t: "reações adversas mais frequentes e graves", p: "A clindamicina mata grande parte das bactérias boas do intestino, e a Clostridioides difficile, resistente a ela, cresce e solta toxinas. Isso pode acontecer até com uma dose única, e a colite pode ser grave. Ex.: paciente que tomou clindamicina antes de uma extração e, dias depois, tem diarreia intensa com febre.", fonte: AHA },
  { t: "forma não ionizada (base livre, lipossolúvel)", p: "A membrana do nervo é feita de lipídios. A molécula sem carga se dissolve na gordura e atravessa; a molécula com carga (ionizada) é repelida e fica do lado de fora. Ex.: no pH normal (7,4), parte da lidocaína está sem carga e atravessa; no abscesso, ácido, quase toda fica com carga e a anestesia falha.", fonte: MAL },
  { t: "Punção no fundo de vestíbulo do 2º pré-molar", p: "O alveolar superior médio desce na altura dos pré-molares. Depositando o anestésico acima do ápice do 2º pré-molar, ele pega o nervo antes de entrar nos dentes, inclusive a raiz mesiovestibular do 1º molar. Ex.: para restaurar o 14 e o 15 com uma picada só, 0,9 a 1,2 mL no fundo de vestíbulo do 15.", fonte: MAL },
  { t: "0,2 a 0,3 mL, devagar (dói)", p: "A papila incisiva é muito inervada e a mucosa do palato é grudada no osso: não há espaço para o líquido. Pouco volume e devagar evitam esticar o tecido de uma vez. Ex.: pressionar com o cabo do espelho ao lado da papila durante a picada diminui a dor.", fonte: MAL },
  { t: "0,2 a 0,3 mL, devagar, dói", p: "A papila incisiva tem muita terminação nervosa e quase nenhum espaço sob a mucosa. Cada gota estica o tecido; por isso pouco volume e bem devagar. Ex.: no bloqueio nasopalatino, 0,2 a 0,3 mL em cerca de 30 segundos.", fonte: MAL },
  { t: "mais dose, mais efeito, até um limite", p: "O efeito cresce enquanto há receptores livres para o fármaco ocupar. Quando quase todos já estão ocupados, mais dose não aumenta o efeito terapêutico, só os efeitos adversos. Ex.: a analgesia do paracetamol não aumenta passando de 1 g por dose, mas o risco para o fígado, sim.", fonte: RANG },
  { t: "0,2 mL por raiz", p: "O espaço do ligamento periodontal é minúsculo, e o anestésico entra sob pressão. Pouco volume basta para chegar ao ápice, e volume a mais causa dor depois da anestesia e sensação de dente alto. Ex.: 1º molar inferior com 2 raízes: 0,2 mL na mesial e 0,2 mL na distal.", fonte: MAL },
  { t: "extremamente dolorosa (mas eficaz)", p: "A agulha entra direto na polpa exposta, que é muito sensível, então a picada dói. Mas o anestésico injetado sob pressão dentro da polpa bloqueia as fibras ali mesmo, e por isso funciona quando as outras técnicas falharam. Ex.: pulpite aguda do 36 que não anestesiou com o bloqueio: depois da abertura, a intrapulpar permite terminar a pulpectomia.", fonte: MAL },
  { t: "polpa exposta, dói, raramente indicada", p: "A intrapulpar só é possível com a polpa já aberta, e a picada direto nela dói. Por isso fica reservada para quando o bloqueio e as técnicas de complemento falham. Ex.: dente com pulpite em que o paciente ainda sente dor depois do bloqueio e da intraligamentar.", fonte: MAL },
  { t: "500 mg de 30 a 60 minutos antes", p: "A ideia é o antibiótico estar no pico no sangue na hora da bacteremia do procedimento. A diretriz da AHA 2021 fala em dose única de 30 a 60 minutos antes; tomar até 1 hora antes cumpre esse objetivo. Ex.: alérgico à penicilina com prótese valvar, extração às 10h: azitromicina 500 mg entre 9h e 9h30.", fonte: AHA },
  { t: "2 g de 30 a 60 minutos antes", p: "A amoxicilina por via oral leva de 30 a 60 minutos para chegar ao pico da concentração plasmática. Dada nesse intervalo, ela está alta no sangue quando o procedimento solta as bactérias (bacteremia). Ex.: paciente com endocardite prévia, raspagem às 14h: amoxicilina 2 g entre 13h e 13h30.", fonte: AHA },
  { t: "A partir de 180 x 110 mmHg: adiar", p: "Nesse nível de pressão arterial o próprio estresse do atendimento, com a adrenalina do corpo, pode desencadear AVC, infarto ou crise hipertensiva. O procedimento eletivo espera o médico controlar a pressão. Ex.: paciente com 185 x 112 mmHg para restauração: remarcar e encaminhar ao médico no mesmo dia.", fonte: MAL },
  { t: "ou mais) = adiar o eletivo", p: "O que é eletivo pode esperar sem prejuízo, e com a pressão arterial nesse nível o risco do atendimento (AVC, infarto) é maior que o benefício. Só urgência (dor forte, infecção) se trata, e com cuidado. Ex.: paciente com 190 x 115 mmHg e dor de dente forte: alivia a dor do jeito menos estressante possível e encaminha ao médico.", fonte: MAL },
  /* ---------- Prescrição ---------- */
  { t: "a 1ª fica retida na farmácia, validade de 10 dias", p: "A ANVISA passou a controlar a venda de antibiótico para frear o uso sem necessidade, que gera bactérias resistentes. A via retida comprova que houve receita, e a validade curta garante que o remédio é para aquela infecção, e não guardado para usar depois por conta própria. Ex.: receita de amoxicilina emitida na segunda-feira: a farmácia retém a 1ª via, e a receita só vale até a quinta da semana seguinte.", fonte: ANV },
  { t: "vale só no estado onde foi emitida", p: "O talão da Notificação de Receita B é numerado e liberado pela Vigilância Sanitária do estado, que controla quem prescreve psicotrópico. Por isso a farmácia de outro estado não aceita: ela não tem como conferir aquela numeração. Ex.: receita azul de midazolam feita em Petrópolis (RJ) não é aceita numa farmácia de Juiz de Fora (MG).", fonte: P344 }
]); })();
